window.AUTH=window.AUTH||{};window.AUTH["99-116"]={"d":"99-116","id":"1999/99-116","n":"Fischer v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/226146/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/fischer-v-united-states-merits","n":77}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep529/usrep529667/usrep529667.pdf","tr":false,"items":[{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Brogan v. United States","cite":"522 U.S. 398","y":1998,"id":"1997/96-1579","sc":1,"op":1,"sum":"Stating that acceptance of bribes by an official of a jail housing federal prisoners pursuant to an agreement with the Government \"was a threat to the integrity and proper operation of the federal program\".","sumSrc":"opinion","by":{"0":"25"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"op":2,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Department of Revenue of Or. v. ACF Indus., Inc.","cite":"510 U.S. 332","y":1994,"id":"1993/92-74","sc":1,"sum":"Section 11503 does not limit the States' discretion to exempt nonrailroad property, but not railroad property, from generally applicable ad valorem property taxes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Good Samaritan Hosp. v. Shalala","cite":"508 U.S. 402","y":1993,"id":"1992/91-2079","sc":1,"op":3,"sum":"Title 42 U. S. C. § 1395f(b)(1) requires the Secretary of Health and Human Services to reimburse the lesser of the \"customary charges\" or the \"reasonable cost[s]\" of providers of health care services to Medicare beneficiaries, while § 1395x(v)(1)(A) empowers the Secretary to issue regulations setting forth the methods to be used in computing reasonable costs, which may include the establishment of appropriate cost …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"INS v. National Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Jarecki v. G.D. Searle & Co.","cite":"367 U.S. 303","y":1961,"id":"1960/151","sc":1,"sum":"1. Development of new products is not \"discovery\" within the meaning of § 456 (a) (2) (B) of the Internal Revenue Code of 1939, as amended; and income resulting from the manufacture and sale of certain patented drugs, cameras, camera equipment and stereo products resulting from inventions is not included within the statutory definition of \"abnormal income,\" in § 456 (a), so as to qualify for Korean War excess …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Kawaauhau v. Geiger","cite":"523 U.S. 57","y":1998,"id":"1997/97-115","sc":1,"sum":"The Court held that \"debts arising from recklessly or negligently inflicted injuries do not fall within the compass of [section 523(a)(6)].\" Therefore, the debt is dischargeable.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"National Collegiate Athletic Ass’n v. Smith","cite":"525 U.S. 459","y":1999,"id":"1998/98-84","sc":1,"sum":"The Court held that dues payments from recipients of federal funds do not suffice to subject the NCAA to suit under Title IX.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"op":2,"sum":"Stating that acceptance of bribes by an official of a jail housing federal prisoners pursuant to an agreement with the Government \"was a threat to the integrity and proper operation of the federal program\".","sumSrc":"opinion","by":{"0":"24"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"op":2,"sum":"Stating that acceptance of bribes by an official of a jail housing federal prisoners pursuant to an agreement with the Government \"was a threat to the integrity and proper operation of the federal program\".","sumSrc":"opinion","by":{"0":"11, 15, 16, 21, 27, 32"}},{"t":"case","label":"United States v. Baylor Univ. Med. Ctr.","cite":"736 F.2d 1039","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/736/1039/","by":{"0":"30"}},{"t":"case","label":"United States v. Copeland","cite":"143 F.3d 1439","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/143/1439/","op":2,"sum":"Holding that federal funds received under a contract to construct military aircraft did not constitute \"benefits\" within the meaning of § 666(b).","sumSrc":"opinion","by":{"0":"19"}},{"t":"case","label":"United States v. Del Toro","cite":"513 F.2d 656","y":1975,"url":"https://www.courtlistener.com/c/F.2d/513/656/","by":{"0":"15, 27"}},{"t":"case","label":"United States v. Hinton","cite":"683 F.2d 195","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/195/","by":{"0":"15, 27"}},{"t":"case","label":"United States v. LaHue","cite":"170 F.3d 1026","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/170/1026/","op":2,"by":{"0":"33"}},{"t":"case","label":"United States v. Marmolejo","cite":"89 F.3d 1185","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/89/1185/","by":{"0":"15, 19, 20, 24"}},{"t":"case","label":"United States v. Mosley","cite":"659 F.2d 812","y":1981,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/659/812/","by":{"0":"15, 27"}},{"t":"case","label":"United States v. Nichols","cite":"40 F.3d 999","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/40/999/","by":{"0":"19, 26"}},{"t":"case","label":"United States v. Rooney","cite":"986 F.2d 31","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/986/31/","by":{"0":"11, 19, 20"}},{"t":"case","label":"United States v. Shabani","cite":"513 U.S. 10","y":1994,"id":"1994/93-981","sc":1,"sum":"In order to establish a violation of §846, the Government need not prove the commission of any overt acts in furtherance of the conspiracy. The statute's plain language does not require an overt act, and such a requirement has not been inferred from congressional silence in other conspiracy statutes, see, e. g., Nash v. United States, 229 U. S. 373. Thus, absent contrary indications, it is presumed that Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"United States v. Westmoreland","cite":"841 F.2d 572","y":1988,"url":"https://www.courtlistener.com/c/F.2d/841/572/","by":{"0":"32"}},{"t":"case","label":"United States v. Zyskind","cite":"118 F.3d 113","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/118/113/","by":{"0":"18"}},{"t":"case","label":"United States Dep’t of Transp. v. Paralyzed Veterans of Am.","cite":"477 U.S. 597","y":1986,"id":"1985/85-289","sc":1,"sum":"Section 504 is not applicable to commercial airlines.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 30, 31"}},{"t":"case","label":"United States v. Zvi, 168 F.3d (2d Cir.), cert. denied","cite":"120 S. Ct. 176","y":1999,"url":"https://www.courtlistener.com/c/S.%20Ct./120/176/","sc":1,"by":{"0":"33"}},{"t":"case","label":"Westfall v. United States","cite":"274 U.S. 256","y":1927,"id":"scdb/1926-121","sc":1,"sum":"1. Section 9 of the Federal Reserve Act, \"ag amended June 21, 1917, is constitutional in so far as it provides that state banks which have.joined the Federal Reserve System, their officers, etc., shall be subject to the penalties of Rev. Stats. § 5209, which punishes misapplications, etc., of a bank’s funds.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Your Home Visiting Nurse Serv., Inc. v. Shalala","cite":"525 U.S. 449","y":1999,"id":"1998/97-1489","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the Board does not have jurisdiction to review a fiscal intermediary's refusal to reopen a reimbursement determination. Moreover, the Court held that the federal-question statute and mandamus statute do not entitle Your Home Visiting Nurse to judicial review of the intermediary's reopening decision.","sumSrc":"Oyez","by":{"0":"3, 22"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"0":"9, 31"}},{"t":"law","label":"Pub. L. No. 99-370","url":"https://www.govinfo.gov/link/statute/100/779","by":{"0":"28"}},{"t":"usc","label":"29 U.S.C. § 794","url":"https://www.law.cornell.edu/uscode/text/29/794","by":{"0":"29"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 421","url":"https://www.law.cornell.edu/uscode/text/42/421","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/42/601","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","stext":{"head":"§1395. Prohibition against any Federal interference","paras":[[0,"Nothing in this subchapter shall be construed to authorize any Federal officer or employee to exercise any supervision or control over the practice of medicine or the manner in which medical services are provided, or over the selection, tenure, or compensation of any officer or employee of any institution, agency, or person providing health services; or to exercise any supervision or control over the administration or operation of any such institution, agency, or person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395. Prohibition against any Federal interference","tname":"The Public Health and Welfare","by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 1395-1395ccc","url":"https://www.law.cornell.edu/uscode/text/42/1395-1395ccc","by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 1395e","url":"https://www.law.cornell.edu/uscode/text/42/1395e","by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 1395f","url":"https://www.law.cornell.edu/uscode/text/42/1395f","subs":["(a)","(b)(1)"],"by":{"0":"31, 12, 16, 42"}},{"t":"usc","label":"42 U.S.C. § 1395g","url":"https://www.law.cornell.edu/uscode/text/42/1395g","subs":["(a)"],"stext":{"head":"§1395g. Payments to providers of services","paras":[[0,"(a) Determination of amount"],[0,"The Secretary shall periodically determine the amount which should be paid under this part to each provider of services with respect to the services furnished by it, and the provider of services shall be paid, at such time or times as the Secretary believes appropriate (but not less often than monthly) and prior to audit or settlement by the Government Accountability Office, from the Federal Hospital Insurance Trust Fund, the amounts so determined, with necessary adjustments on account of previously made overpayments or underpayments; except that no such payments shall be made to any provider unless it has furnished such information as the Secretary may request in order to determine the amounts due such provider under this part for the period with respect to which the amounts are being paid or any prior period."],[0,"(b) Conditions"],[0,"No payment shall be made to a provider of services which is a hospital for or with respect to services furnished by it for any period with respect to which it is deemed, under section 1395x(w)(2) of this title, to have in effect an arrangement with a quality improvement organization for the conduct of utilization review activities by such organization unless such hospital has paid to such organization the amount due (as determined pursuant to such section) to such organization for the review activities conducted by it pursuant to such arrangements or such hospital has provided assurances satisfactory to the Secretary that such organization will promptly be paid the amount so due to it from the proceeds of the payment claimed by the hospital. Payment under this subchapter for utilization review activities provided by a quality improvement organization pursuant to an arrangement or deemed arrangement with a hospital under section 1395x(w)(2) of this title shall be calculated without any requirement that the reasonable cost of such activities be apportioned among the patients of such hospital, if any, to whom such activities were not applicable."],[0,"(c) Payments under assignment or power of attorney"],[0,"No payment which may be made to a provider of services under this subchapter for any service furnished to an individual shall be made to any other person under an assignment or power of attorney; but nothing in this subsection shall be construed (1) to prevent the making of such a payment in accordance with an assignment from the provider if such assignment is made to a governmental agency or entity or is established by or pursuant to the order of a court of competent jurisdiction, or (2) to preclude an agent of the provider of services from receiving any such payment if (but only if) such agent does so pursuant to an agency agreement under which the compensation to be paid to the agent for his services for or in connection with the billing or collection of payments due such provider under this subchapter is unrelated (directly or indirectly) to the amount of such payments or the billings therefor, and is not dependent upon the actual collection of any such payment."],[0,"(d) Accrual of interest on balance of excess or deficit not paid"],[0,"Whenever a final determination is made that the amount of payment made under this part to a provider of services was in excess of or less than the amount of payment that is due, and payment of such excess or deficit is not made (or effected by offset) within 30 days of the date of the determination, interest shall accrue on the balance of such excess or deficit not paid or offset (to the extent that the balance is owed by or owing to the provider) at a rate determined in accordance with the regulations of the Secretary of the Treasury applicable to charges for late payments (or, in the case of such a determination made with respect to a payment made on or after March 27, 2020, and during the emergency period described in section 1320b–5(g)(1)(B) of this title under the program under subsection (e)(3), including such program as expanded pursuant to subsection (f), at a rate of 4 percent)."],[0,"(e) Periodic interim payments"],[0,"(1) The Secretary shall provide payment under this part for inpatient hospital services furnished by a subsection (d) hospital (as defined in section 1395ww(d)(1)(B) of this title, and including a distinct psychiatric or rehabilitation unit of such a hospital) and a subsection (d) Puerto Rico hospital (as defined in section 1395ww(d)(9)(A) of this title) on a periodic interim payment basis (rather than on the basis of bills actually submitted) in the following cases:"],[1,"(A) Upon the request of a hospital which is paid through an agency or organization with an agreement with the Secretary under section 1395h of this title, if the agency or organization, for three consecutive calendar months, fails to meet the requirements of subsection (c)(2) of such section and if the hospital meets the requirements (in effect as of October 1, 1986) applicable to payment on such a basis, until such time as the agency or organization meets such requirements for three consecutive calendar months."],[1,"(B) In the case of a hospital that—"],[2,"(i) has a disproportionate share adjustment percentage (as established in clause (iv) of such section) of at least 5.1 percent (as computed for purposes of establishing the average standardized amounts for discharges occurring during fiscal year 1987), and"],[2,"(ii) requests payment on such basis,"],[1,"but only if the hospital was being paid for inpatient hospital services on such a periodic interim payment basis as of June 30, 1987, and continues to meet the requirements (in effect as of October 1, 1986) applicable to payment on such a basis."],[1,"(C) In the case of a hospital that—"],[2,"(i) is located in a rural area,"],[2,"(ii) has 100 or fewer beds, and"],[2,"(iii) requests payment on such basis,"],[1,"but only if the hospital was being paid for inpatient hospital services on such a periodic interim payment basis as of June 30, 1987, and continues to meet the requirements (in effect as of October 1, 1986) applicable to payment on such a basis."],[0,"(2) The Secretary shall provide (or continue to provide) for payment on a periodic interim payment basis (under the standards established under section 405.454(j) of title 42, Code of Federal Regulations, as in effect on October 1, 1986, in the cases described in subparagraphs (A) through (D)) with respect to—"],[1,"(A) inpatient hospital services of a hospital that is not a subsection (d) hospital (as defined in section 1395ww(d)(1)(B) of this title);"],[1,"(B) a hospital which is receiving payment under a State hospital reimbursement system under section 1395f(b)(3) or 1395ww(c) of this title, if payment on a periodic interim payment basis is an integral part of such reimbursement system;"],[1,"(C) extended care services;"],[1,"(D) hospice care; and"],[1,"(E) inpatient critical access hospital services;"],[0,"if the provider of such services elects to receive, and qualifies for, such payments."],[0,"(3) Subject to subsection (f), in the case of a subsection (d) hospital or a subsection (d) Puerto Rico hospital (as defined for purposes of section 1395ww of this title) which has significant cash flow problems resulting from operations of its intermediary or from unusual circumstances of the hospital's operation, the Secretary may make available appropriate accelerated payments."],[0,"(4) A hospital created by the merger or consolidation of 2 or more hospitals or hospital campuses shall be eligible to receive periodic interim payment on the basis described in paragraph (1)(B) if—"],[1,"(A) at least one of the hospitals or campuses received periodic interim payment on such basis prior to the merger or consolidation; and"],[1,"(B) the merging or consolidating hospitals or campuses would each meet the requirement of paragraph (1)(B)(i) if such hospitals or campuses were treated as independent hospitals for purposes of this subchapter."],[0,"(f) Expansion of accelerated payment program during COVID–19 public health emergency"],[0,"(1) During the emergency period described in section 1320b–5(g)(1)(B) of this title, the Secretary shall expand the program under subsection (e)(3) pursuant to paragraph (2)."],[0,"(2) In expanding the program under subsection (e)(3), the following shall apply:"],[1,"(A)(i) In addition to the hospitals described in subsection (e)(3), the following hospitals shall be eligible to participate in the program:"],[2,"(I) Hospitals described in clause (iii) of section 1395ww(d)(1)(B) of this title."],[2,"(II) Hospitals described in clause (v) of such section."],[2,"(III) Critical access hospitals (as defined in section 1395x(mm)(1) of this title)."],[1,"(ii) Subject to appropriate safeguards against fraud, waste, and abuse, upon a request of a hospital described in clause (i), the Secretary shall (or, with respect to requests submitted to the Secretary after April 26, 2020, may) provide accelerated payments under the program to such hospital."],[1,"(B) Upon the request of the hospital, the Secretary may do any of the following:"],[2,"(i) Make accelerated payments on a periodic or lump sum basis."],[2,"(ii) Increase the amount of payment that would otherwise be made to hospitals under the program up to 100 percent (or, in the case of critical access hospitals, up to 125 percent)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395g?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395g. Payments to providers of services","tname":"The Public Health and Welfare","by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 1395n","url":"https://www.law.cornell.edu/uscode/text/42/1395n","subs":["(a)","(c)"],"by":{"0":"31, 12, 12"}},{"t":"usc","label":"42 U.S.C. § 1395x","url":"https://www.law.cornell.edu/uscode/text/42/1395x","subs":["(v)(1)(A)"],"stext":{"head":"§1395x. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Spell of illness"],[0,"The term \"spell of illness\" with respect to any individual means a period of consecutive days—"],[1,"(1) beginning with the first day (not included in a previous spell of illness) (A) on which such individual is furnished inpatient hospital services, inpatient critical access hospital services or extended care services, and (B) which occurs in a month for which he is entitled to benefits under part A, and"],[1,"(2) ending with the close of the first period of 60 consecutive days thereafter on each of which he is neither an inpatient of a hospital or critical access hospital nor an inpatient of a facility described in section 1395i–3(a)(1) of this title or subsection (y)(1)."],[0,"(b) Inpatient hospital services"],[0,"The term \"inpatient hospital services\" means the following items and services furnished to an inpatient of a hospital and (except as provided in paragraph (3)) by the hospital—"],[1,"(1) bed and board;"],[1,"(2) such nursing services and other related services, such use of hospital facilities, and such medical social services as are ordinarily furnished by the hospital for the care and treatment of inpatients, and such drugs, biologicals, supplies, appliances, and equipment, for use in the hospital, as are ordinarily furnished by such hospital for the care and treatment of inpatients; and"],[1,"(3) such other diagnostic or therapeutic items or services, furnished by the hospital or by others under arrangements with them made by the hospital, as are ordinarily furnished to inpatients either by such hospital or by others under such arrangements;"],[0,"excluding, however—"],[1,"(4) medical or surgical services provided by a physician, resident, or intern, services described by subsection (s)(2)(K), certified nurse-midwife services, qualified psychologist services, and services of a certified registered nurse anesthetist; and"],[1,"(5) the services of a private-duty nurse or other private-duty attendant."],[0,"Paragraph (4) shall not apply to services provided in a hospital by—"],[1,"(6) an intern or a resident-in-training under a teaching program approved by the Council on Medical Education of the American Medical Association or, in the case of an osteopathic hospital, approved by the Committee on Hospitals of the Bureau of Professional Education of the American Osteopathic Association, or, in the case of services in a hospital or osteopathic hospital by an intern or resident-in-training in the field of dentistry, approved by the Council on Dental Education of the American Dental Association, or in the case of services in a hospital or osteopathic hospital by an intern or resident-in-training in the field of podiatry, approved by the Council on Podiatric Medical Education of the American Podiatric Medical Association; or"],[1,"(7) a physician where the hospital has a teaching program approved as specified in paragraph (6), if (A) the hospital elects to receive any payment due under this subchapter for reasonable costs of such services, and (B) all physicians in such hospital agree not to bill charges for professional services rendered in such hospital to individuals covered under the insurance program established by this subchapter."],[0,"(c) Inpatient psychiatric hospital services"],[0,"The term \"inpatient psychiatric hospital services\" means inpatient hospital services furnished to an inpatient of a psychiatric hospital."],[0,"(d) Supplier"],[0,"The term \"supplier\" means, unless the context otherwise requires, a physician or other practitioner, a facility, or other entity (other than a provider of services) that furnishes items or services under this subchapter."],[0,"(e) Hospital"],[0,"The term \"hospital\" (except for purposes of sections 1395f(d), 1395f(f), and 1395n(b) of this title, subsection (a)(2) of this section, paragraph (7) of this subsection, and subsection (i) of this section) means an institution which—"],[1,"(1) is primarily engaged in providing, by or under the supervision of physicians, to inpatients (A) diagnostic services and therapeutic services for medical diagnosis, treatment, and care of injured, disabled, or sick persons, or (B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons;"],[1,"(2) maintains clinical records on all patients;"],[1,"(3) has bylaws in effect with respect to its staff of physicians;"],[1,"(4) has a requirement that every patient with respect to whom payment may be made under this subchapter must be under the care of a physician, except that a patient receiving qualified psychologist services (as defined in subsection (ii)) may be under the care of a clinical psychologist with respect to such services to the extent permitted under State law;"],[1,"(5) provides 24-hour nursing service rendered or supervised by a registered professional nurse, and has a licensed practical nurse or registered professional nurse on duty at all times; except that until January 1, 1979, the Secretary is authorized to waive the requirement of this paragraph for any one-year period with respect to any institution, insofar as such requirement relates to the provision of twenty-four-hour nursing service rendered or supervised by a registered professional nurse (except that in any event a registered professional nurse must be present on the premises to render or supervise the nursing service provided, during at least the regular daytime shift), where immediately preceding such one-year period he finds that—"],[2,"(A) such institution is located in a rural area and the supply of hospital services in such area is not sufficient to meet the needs of individuals residing therein,"],[2,"(B) the failure of such institution to qualify as a hospital would seriously reduce the availability of such services to such individuals, and"],[2,"(C) such institution has made and continues to make a good faith effort to comply with this paragraph, but such compliance is impeded by the lack of qualified nursing personnel in such area;"],[1,"(6)(A) has in effect a hospital utilization review plan which meets the requirements of subsection (k) and (B) has in place a discharge planning process that meets the requirements of subsection (ee);"],[1,"(7) in the case of an institution in any State in which State or applicable local law provides for the licensing of hospitals, (A) is licensed pursuant to such law or (B) is approved, by the agency of such State or locality responsible for licensing hospitals, as meeting the standards established for such licensing;"],[1,"(8) has in effect an overall plan and budget that meets the requirements of subsection (z); and"],[1,"(9) meets such other requirements as the Secretary finds necessary in the interest of the health and safety of individuals who are furnished services in the institution."],[0,"For purposes of subsection (a)(2), such term includes any institution which meets the requirements of paragraph (1) of this subsection. For purposes of sections 1395f(d) and 1395n(b) of this title (including determination of whether an individual received inpatient hospital services or diagnostic services for purposes of such sections), section 1395f(f)(2) of this title, and subsection (i) of this section, such term includes any institution which (i) meets the requirements of paragraphs (5) and (7) of this subsection, (ii) is not primarily engaged in providing the services described in subsection (j)(1)(A) and (iii) is primarily engaged in providing, by or under the supervision of individuals referred to in paragraph (1) of subsection (r), to inpatients diagnostic services and therapeutic services for medical diagnosis, treatment, and care of injured, disabled, or sick persons, or rehabilitation services for the rehabilitation of injured, disabled, or sick persons. For purposes of section 1395f(f)(1) of this title, such term includes an institution which (i) is a hospital for purposes of sections 1395f(d), 1395f(f)(2), and 1395n(b) of this title and (ii) is accredited by a national accreditation body recognized by the Secretary under section 1395bb(a) of this title, or is accredited by or approved by a program of the country in which such institution is located if the Secretary finds the accreditation or comparable approval standards of such program to be essentially equivalent to those of such a national accreditation body..1 Notwithstanding the preceding provisions of this subsection, such term shall not, except for purposes of subsection (a)(2), include any institution which is primarily for the care and treatment of mental diseases unless it is a psychiatric hospital (as defined in subsection (f)). The term \"hospital\" also includes a religious nonmedical health care institution (as defined in subsection (ss)(1)), but only with respect to items and services ordinarily furnished by such institution to inpatients, and payment may be made with respect to services provided by or in such an institution only to such extent and under such conditions, limitations, and requirements (in addition to or in lieu of the conditions, limitations, and requirements otherwise applicable) as may be provided in regulations consistent with section 1395i–5 of this title. For provisions deeming certain requirements of this subsection to be met in the case of accredited institutions, see section 1395bb of this title. The term \"hospital\" also includes a facility of fifty beds or less which is located in an area determined by the Secretary to meet the definition relating to a rural area described in subparagraph (A) of paragraph (5) of this subsection and which meets the other requirements of this subsection, except that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395x?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395x. Definitions","tname":"The Public Health and Welfare","by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 1395bb","url":"https://www.law.cornell.edu/uscode/text/42/1395bb","by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 1395ww","url":"https://www.law.cornell.edu/uscode/text/42/1395ww","subs":["(d)","(d)(5)(F)"],"stext":{"head":"§1395ww. Payments to hospitals for inpatient hospital services","paras":[[0,"(a) Determination of costs for inpatient hospital services; limitations; exemptions; \"operating costs of inpatient hospital services\" defined"],[0,"(1)(A)(i) The Secretary, in determining the amount of the payments that may be made under this subchapter with respect to operating costs of inpatient hospital services (as defined in paragraph (4)) shall not recognize as reasonable (in the efficient delivery of health services) costs for the provision of such services by a hospital for a cost reporting period to the extent such costs exceed the applicable percentage (as determined under clause (ii)) of the average of such costs for all hospitals in the same grouping as such hospital for comparable time periods."],[0,"(ii) For purposes of clause (i), the applicable percentage for hospital cost reporting periods beginning—"],[1,"(I) on or after October 1, 1982, and before October 1, 1983, is 120 percent;"],[1,"(II) on or after October 1, 1983, and before October 1, 1984, is 115 percent; and"],[1,"(III) on or after October 1, 1984, is 110 percent."],[0,"(B)(i) For purposes of subparagraph (A) the Secretary shall establish case mix indexes for all short-term hospitals, and shall set limits for each hospital based upon the general mix of types of medical cases with respect to which such hospital provides services for which payment may be made under this subchapter."],[0,"(ii) The Secretary shall set such limits for a cost reporting period of a hospital—"],[1,"(I) by updating available data for a previous period to the immediate preceding cost reporting period by the estimated average rate of change of hospital costs industry-wide, and"],[1,"(II) by projecting for the cost reporting period by the applicable percentage increase (as defined in subsection (b)(3)(B))."],[0,"(C) The limitation established under subparagraph (A) for any hospital shall in no event be lower than the allowable operating costs of inpatient hospital services (as defined in paragraph (4)) recognized under this subchapter for such hospital for such hospital's last cost reporting period prior to the hospital's first cost reporting period for which this section is in effect."],[0,"(D) Subparagraph (A) shall not apply to cost reporting periods beginning on or after October 1, 1983."],[0,"(2) The Secretary shall provide for such exemptions from, and exceptions and adjustments to, the limitation established under paragraph (1)(A) as he deems appropriate, including those which he deems necessary to take into account—"],[1,"(A) the special needs of sole community hospitals, of new hospitals, of risk based health maintenance organizations, and of hospitals which provide atypical services or essential community services, and to take into account extraordinary circumstances beyond the hospital's control, medical and paramedical education costs, significantly fluctuating population in the service area of the hospital, and unusual labor costs,"],[1,"(B) the special needs of psychiatric hospitals and of public or other hospitals that serve a significantly disproportionate number of patients who have low income or are entitled to benefits under part A of this subchapter, and"],[1,"(C) a decrease in the inpatient hospital services that a hospital provides and that are customarily provided directly by similar hospitals which results in a significant distortion in the operating costs of inpatient hospital services."],[0,"(3) The limitation established under paragraph (1)(A) shall not apply with respect to any hospital which—"],[1,"(A) is located outside of a standard metropolitan statistical area, and"],[1,"(B)(i) has less than 50 beds, and"],[1,"(ii) was in operation and had less than 50 beds on September 3, 1982."],[0,"(4) For purposes of this section, the term \"operating costs of inpatient hospital services\" includes all routine operating costs, ancillary service operating costs, and special care unit operating costs with respect to inpatient hospital services as such costs are determined on an average per admission or per discharge basis (as determined by the Secretary), and includes the costs of all services for which payment may be made under this subchapter that are provided by the hospital (or by an entity wholly owned or operated by the hospital) to the patient during the 3 days (or, in the case of a hospital that is not a subsection (d) hospital, during the 1 day) immediately preceding the date of the patient's admission if such services are diagnostic services (including clinical diagnostic laboratory tests) or are other services related to the admission (as defined by the Secretary). Such term does not include costs of approved educational activities, a return on equity capital, other capital-related costs (as defined by the Secretary for periods before October 1, 1987), for cost reporting periods beginning on or after October 1, 2020, costs related to hematopoietic stem cell acquisition for the purpose of an allogeneic hematopoietic stem cell transplant (as described in subsection (d)(5)(M)), or costs with respect to administering blood clotting factors to individuals with hemophilia. In applying the first sentence of this paragraph, the term \"other services related to the admission\" includes all services that are not diagnostic services (other than ambulance and maintenance renal dialysis services) for which payment may be made under this subchapter that are provided by a hospital (or an entity wholly owned or operated by the hospital) to a patient—"],[1,"(A) on the date of the patient's inpatient admission; or"],[1,"(B) during the 3 days (or, in the case of a hospital that is not a subsection (d) hospital, during the 1 day) immediately preceding the date of such admission unless the hospital demonstrates (in a form and manner, and at a time, specified by the Secretary) that such services are not related (as determined by the Secretary) to such admission."],[0,"(b) Computation of payment; definitions; exemptions; adjustments"],[0,"(1) Notwithstanding section 1395f(b) of this title but subject to the provisions of section 1395e of this title, if the operating costs of inpatient hospital services (as defined in subsection (a)(4)) of a hospital (other than a subsection (d) hospital, as defined in subsection (d)(1)(B) and other than a rehabilitation facility described in subsection (j)(1)) for a cost reporting period subject to this paragraph—"],[1,"(A) are less than or equal to the target amount (as defined in paragraph (3)) for that hospital for that period, the amount of the payment with respect to such operating costs payable under part A on a per discharge or per admission basis (as the case may be) shall be equal to the amount of such operating costs, plus—"],[2,"(i) 15 percent of the amount by which the target amount exceeds the amount of the operating costs, or"],[2,"(ii) 2 percent of the target amount,"],[1,"whichever is less;"],[1,"(B) are greater than the target amount but do not exceed 110 percent of the target amount, the amount of the payment with respect to those operating costs payable under part A on a per discharge basis shall equal the target amount; or"],[1,"(C) are greater than 110 percent of the target amount, the amount of the payment with respect to such operating costs payable under part A on a per discharge or per admission basis (as the case may be) shall be equal to (i) the target amount, plus (ii) in the case of cost reporting periods beginning on or after October 1, 1991, an additional amount equal to 50 percent of the amount by which the operating costs exceed 110 percent of the target amount (except that such additional amount may not exceed 10 percent of the target amount) after any exceptions or adjustments are made to such target amount for the cost reporting period;"],[0,"plus the amount, if any, provided under paragraph (2), except that in no case may the amount payable under this subchapter (other than on the basis of a DRG prospective payment rate determined under subsection (d)) with respect to operating costs of inpatient hospital services exceed the maximum amount payable with respect to such costs pursuant to subsection (a)."],[0,"(2)(A) Except as provided in subparagraph (E), in addition to the payment computed under paragraph (1), in the case of an eligible hospital (described in subparagraph (B)) for a cost reporting period beginning on or after October 1, 1997, the amount of payment on a per discharge basis under paragraph (1) shall be increased by the lesser of—"],[1,"(i) 50 percent of the amount by which the operating costs are less than the expected costs (as defined in subparagraph (D)) for the period; or"],[1,"(ii) 1 percent of the target amount for the period."],[0,"(B) For purposes of this paragraph, an \"eligible hospital\" means with respect to a cost reporting period, a hospital—"],[1,"(i) that has received payments under this subsection for at least 3 full cost reporting periods before that cost reporting period, and"],[1,"(ii) whose operating costs for the period are less than the least of its target amount, its trended costs (as defined in subparagraph (C)), or its expected costs (as defined in subparagraph (D)) for the period."],[0,"(C) For purposes of subparagraph (B)(ii), the term \"trended costs\" means for a hospital cost reporting period ending in a fiscal year—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395ww?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1395ww. Payments to hospitals for inpatient hospital services","tname":"The Public Health and Welfare","by":{"0":"20, 22"}},{"t":"law","label":"Pub. L. No. 99-646","url":"https://www.govinfo.gov/link/statute/100/3612","by":{"0":"27"}},{"t":"usc","label":"7 U.S.C. § 2018","url":"https://www.law.cornell.edu/uscode/text/7/2018","subs":["(a)(1)"],"by":{"0":"31, 31"}},{"t":"usc","label":"7 U.S.C. § 2020","url":"https://www.law.cornell.edu/uscode/text/7/2020","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 215","url":"https://www.law.cornell.edu/uscode/text/18/215","by":{"0":"27"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"0":"2, 33"}},{"t":"usc","label":"18 U.S.C. § 641","url":"https://www.law.cornell.edu/uscode/text/18/641","by":{"0":"13"}},{"t":"usc","label":"18 U.S.C. § 665","url":"https://www.law.cornell.edu/uscode/text/18/665","stext":{"head":"§665. Theft or embezzlement from employment and training funds; improper inducement; obstruction of investigations","paras":[[0,"(a) Whoever, being an officer, director, agent, or employee of, or connected in any capacity with any agency or organization receiving financial assistance or any funds under title I of the Workforce Innovation and Opportunity Act or title I of the Workforce Investment Act of 1998 knowingly enrolls an ineligible participant, embezzles, willfully misapplies, steals, or obtains by fraud any of the moneys, funds, assets, or property which are the subject of a financial assistance agreement or contract pursuant to such Act shall be fined under this title or imprisoned for not more than 2 years, or both; but if the amount so embezzled, misapplied, stolen, or obtained by fraud does not exceed $1,000, such person shall be fined under this title or imprisoned not more than 1 year, or both."],[0,"(b) Whoever, by threat or procuring dismissal of any person from employment or of refusal to employ or refusal to renew a contract of employment in connection with a financial assistance agreement or contract under title I of the Workforce Innovation and Opportunity Act or title I of the Workforce Investment Act of 1998 induces any person to give up any money or thing of any value to any person (including such organization or agency receiving funds) shall be fined under this title, or imprisoned not more than 1 year, or both."],[0,"(c) Whoever willfully obstructs or impedes or willfully endeavors to obstruct or impede, an investigation or inquiry under title I of the Workforce Innovation and Opportunity Act or title I of the Workforce Investment Act of 1998, or the regulations thereunder, shall be punished by a fine under this title, or by imprisonment for not more than 1 year, or by both such fine and imprisonment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/665?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§665. Theft or embezzlement from employment and training funds; improper inducement; obstruction of investigations","tname":"Crimes and Criminal Procedure","by":{"0":"13"}},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(a)","(a)(1)(A)","(a)(1)(B)","(a)(2)","(b)","(c)"],"stext":{"head":"§666. Theft or bribery concerning programs receiving Federal funds","paras":[[0,"(a) Whoever, if the circumstance described in subsection (b) of this section exists—"],[1,"(1) being an agent of an organization, or of a State, local, or Indian tribal government, or any agency thereof—"],[2,"(A) embezzles, steals, obtains by fraud, or otherwise without authority knowingly converts to the use of any person other than the rightful owner or intentionally misapplies, property that—"],[3,"(i) is valued at $5,000 or more, and"],[3,"(ii) is owned by, or is under the care, custody, or control of such organization, government, or agency; or"],[2,"(B) corruptly solicits or demands for the benefit of any person, or accepts or agrees to accept, anything of value from any person, intending to be influenced or rewarded in connection with any business, transaction, or series of transactions of such organization, government, or agency involving any thing of value of $5,000 or more; or"],[1,"(2) corruptly gives, offers, or agrees to give anything of value to any person, with intent to influence or reward an agent of an organization or of a State, local or Indian tribal government, or any agency thereof, in connection with any business, transaction, or series of transactions of such organization, government, or agency involving anything of value of $5,000 or more;"],[0,"shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(b) The circumstance referred to in subsection (a) of this section is that the organization, government, or agency receives, in any one year period, benefits in excess of $10,000 under a Federal program involving a grant, contract, subsidy, loan, guarantee, insurance, or other form of Federal assistance."],[0,"(c) This section does not apply to bona fide salary, wages, fees, or other compensation paid, or expenses paid or reimbursed, in the usual course of business."],[0,"(d) As used in this section—"],[1,"(1) the term \"agent\" means a person authorized to act on behalf of another person or a government and, in the case of an organization or government, includes a servant or employee, and a partner, director, officer, manager, and representative;"],[1,"(2) the term \"government agency\" means a subdivision of the executive, legislative, judicial, or other branch of government, including a department, independent establishment, commission, administration, authority, board, and bureau, and a corporation or other legal entity established, and subject to control, by a government or governments for the execution of a governmental or intergovernmental program;"],[1,"(3) the term \"local\" means of or pertaining to a political subdivision within a State;"],[1,"(4) the term \"State\" includes a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States; and"],[1,"(5) the term \"in any one-year period\" means a continuous period that commences no earlier than twelve months before the commission of the offense or that ends no later than twelve months after the commission of the offense. Such period may include time both before and after the commission of the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/666?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§666. Theft or bribery concerning programs receiving Federal funds","tname":"Crimes and Criminal Procedure","by":{"0":"passim, 9, 25, 2, 9, 10, 24, 2, 10, 24, passim, 23, 25, 27, 28"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","by":{"0":"2, 33"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"0":"2, 33"}},{"t":"usc","label":"18 U.S.C. § 1957","url":"https://www.law.cornell.edu/uscode/text/18/1957","by":{"0":"20"}},{"t":"usc","label":"20 U.S.C. § 1094","url":"https://www.law.cornell.edu/uscode/text/20/1094","subs":["(a)(1)","(a)(3)"],"by":{"0":"31, 31"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"42 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/42/1347","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","by":{"0":"29"}},{"t":"usc","label":"42 U.S.C. § 5301","url":"https://www.law.cornell.edu/uscode/text/42/5301","by":{"0":"18"}},{"t":"reg","label":"38 Fed. Reg. 17,978","url":"https://www.govinfo.gov/link/fr/38/17978","by":{"0":"30"}}]};